# A command can choose a word from a number.
def label [n: int] {
  if $n > 1 { "big" } else { "small" }
}
label 3 | str length | math abs | into string

# Define a command and call it with one argument.
def greet [name: string] {
  $"hi ($name)"
}
greet nushell

# scope modules lists the module you defined.
module demo {}
scope modules | where name == "demo" | length

# A second name is found the same way.
module tools {}
scope modules | where name == "tools" | length

# Read the name column after the filter.
module demo {}
scope modules | where name == "demo" | get name | length

# each can read every module name.
module demo {}
scope modules | each {|m| $m.name} | length

# Export a greeting and call it by its module name.
module greet {
  export def hello [name: string] {
    $"hi ($name)"
  }
}
use greet
greet hello tips

# job list shows the jobs still recorded.
job spawn { 3 }
job list | length | math abs

# each can read the id of each job.
job spawn { 1 }
job list | each {|j| $j.id} | length
